code.cpp:
class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        int freq[11] = {0};

        for (const string& w : words) {
            int f = computeF(w);
            freq[f]++;
        }

        int suffix[12] = {0};
        for (int i = 9; i >= 1; i--) {
            suffix[i] = suffix[i + 1] + freq[i + 1];
        }

        vector<int> answer;
        answer.reserve(queries.size());
        for (const string& q : queries) {
            int f = computeF(q);
            answer.push_back(suffix[f]);
        }
        return answer;
    }

private:
    int computeF(const string& s) {
        char smallest = 'z' + 1;
        int count = 0;
        for (char c : s) {
            if (c < smallest) {
                smallest = c;
                count = 1;
            } else if (c == smallest) {
                count++;
            }
        }
        return count;
    }
};
